{"relative_path": "factory/temp/factory/infra/validation.py", "function_name": "_feedback_from_audit", "new_function_code": "def _feedback_from_audit(findings: list['ReviewFinding'], audit: 'AuditResult') -> dict[str, str]:
    """R1 (baziforecaster-nw9ov): render red-team augmented findings + risks into a
    task_id -> prior-feedback text map for the rerun coder brief."""
    out: dict[str, list[str]] = {}
    for f in findings:
        _process_finding(f, out)
    risks = getattr(audit, 'risks', None) or []
    for r in risks:
